custom_css:
/* Crimson Night Theme */
.card {
  box-shadow: 0 8px 25px -5px hsl(0 85% 20% / 0.3);
}

.button:hover {
  box-shadow: 0 0 20px hsl(0 85% 60% / 0.3);
}

/* Ocean Breeze Theme */
.manga-card {
  backdrop-filter: blur(10px);
  background: linear-gradient(135deg, hsl(210 30% 20% / 0.8), hsl(210 25% 15% / 0.9));
}

.reader-page {
  filter: brightness(1.05) contrast(1.1);
}

/* Sunset Theme */
:root {
  --gradient-sunset: linear-gradient(135deg, hsl(25 90% 65%), hsl(15 85% 60%));
}

.hero-section {
  background: var(--gradient-sunset);
}

.chapter-card:hover {
  transform: translateY(-4px) scale(1.02);
  box-shadow: 0 12px 30px -8px hsl(25 90% 45% / 0.4);
}

/* Forest Zen Theme */
.reading-progress {
  background: linear-gradient(90deg, hsl(140 60% 55%), hsl(120 55% 50%));
}

.card {
  border: 1px solid hsl(140 30% 20% / 0.5);
}

body {
  --shadow-soft: 0 4px 15px -2px hsl(140 40% 10% / 0.3);
}

/* Cyber Purple Theme */
.nav-item {
  border: 1px solid hsl(270 80% 65% / 0.3);
  box-shadow: 0 0 10px hsl(270 80% 65% / 0.2);
}

.manga-page {
  filter: contrast(1.1) saturate(1.1);
}

.button {
  background: linear-gradient(135deg, hsl(270 80% 65%), hsl(290 75% 60%));
  text-shadow: 0 0 8px hsl(270 80% 80% / 0.8);
}
